/**
 * Form field helpers for the engine worker. Values are written through MuPDF's widget setters so the
 * widget appearance is marked dirty and regenerated by `widget.update()`; nothing here writes page
 * content or appearance streams by hand. PDF scripts are never executed: the only "calculation" support
 * is a declarative evaluator for Acrobat's AFSimple_Calculate (SUM/PRD/AVG/MIN/MAX), run only when the
 * caller passes `calculate: true` (the user enabled PDF JavaScript in Settings).
 */
import * as mupdf from 'mupdf';
import type { EngineContext } from '../../context';
import type { FieldOption, FieldType, FormWidget, SetValueArgs } from './types';

const FF_READ_ONLY = 1;
const FF_REQUIRED = 2;
const TX_MULTILINE = 1 << 12;
const TX_PASSWORD = 1 << 13;
const TX_COMB = 1 << 24;
const BTN_NO_TOGGLE_TO_OFF = 1 << 14;
const CH_EDIT = 1 << 18;
const CH_MULTI_SELECT = 1 << 21;
const ANNOT_HIDDEN = 2;
const ANNOT_NO_VIEW = 32;

const TYPE_MAP: Record<string, FieldType> = {
  text: 'text',
  checkbox: 'checkbox',
  radiobutton: 'radio',
  combobox: 'combobox',
  listbox: 'listbox',
  button: 'button',
  signature: 'signature',
};

function safe<T>(fn: () => T, fallback: T): T {
  try {
    return fn();
  } catch {
    return fallback;
  }
}

/** Safe nested lookup: mupdf.js throws when `get` is called on its shared Null object. */
function at(obj: mupdf.PDFObject, ...keys: string[]): mupdf.PDFObject {
  return obj.isNull() ? obj : obj.get(...keys);
}

function acroFormOf(pdf: mupdf.PDFDocument): mupdf.PDFObject {
  return pdf.getTrailer().get('Root', 'AcroForm');
}

function text(obj: mupdf.PDFObject): string {
  if (obj.isString()) return obj.asString();
  if (obj.isName()) return obj.asName();
  if (obj.isStream()) return safe(() => obj.readStream().asString(), '');
  if (obj.isNumber()) return String(obj.asNumber());
  return '';
}

export function parseDA(da: string): { size: number; color: [number, number, number] } {
  const tokens = da.split(/\s+/).filter(Boolean);
  let size = 0;
  let color: [number, number, number] = [0, 0, 0];
  for (let i = 0; i < tokens.length; i++) {
    const n = (k: number) => Number(tokens[i - k]);
    if (tokens[i] === 'Tf' && i >= 1 && Number.isFinite(n(1))) size = n(1);
    else if (tokens[i] === 'g' && i >= 1 && Number.isFinite(n(1))) color = [n(1), n(1), n(1)];
    else if (tokens[i] === 'rg' && i >= 3 && [1, 2, 3].every((k) => Number.isFinite(n(k))))
      color = [n(3), n(2), n(1)];
    else if (tokens[i] === 'k' && i >= 4 && [1, 2, 3, 4].every((k) => Number.isFinite(n(k)))) {
      const [c, m, y, k] = [n(4), n(3), n(2), n(1)];
      color = [(1 - c) * (1 - k), (1 - m) * (1 - k), (1 - y) * (1 - k)];
    }
  }
  return { size: Math.max(0, size), color };
}

/** The terminal field dictionary for a widget (the widget itself when field and widget are merged). */
export function fieldOf(widget: mupdf.PDFObject): mupdf.PDFObject {
  if (widget.get('T').isString() || widget.get('FT').isName()) return widget;
  const parent = widget.get('Parent');
  return parent.isDictionary() ? parent : widget;
}

export function onStateOf(widget: mupdf.PDFObject): string | undefined {
  const normal = widget.get('AP', 'N');
  let state: string | undefined;
  if (normal.isDictionary())
    normal.forEach((_value, key) => {
      if (state === undefined && typeof key === 'string' && key !== 'Off' && !normal.get(key).isNull())
        state = key;
    });
  return state;
}

function exportValueOf(field: mupdf.PDFObject, onState: string): string {
  const opt = field.getInheritable('Opt');
  if (opt.isArray() && /^\d+$/.test(onState)) {
    const index = Number(onState);
    if (index < opt.length) return text(opt.get(index));
  }
  return onState;
}

function optionsOf(widget: mupdf.PDFWidget): FieldOption[] {
  const labels = safe(() => widget.getOptions(false), [] as string[]);
  const values = safe(() => widget.getOptions(true), [] as string[]);
  return labels.map((label, i) => ({ label, value: values[i] ?? label }));
}

function choiceValues(field: mupdf.PDFObject): string[] {
  const v = field.getInheritable('V');
  if (v.isArray()) {
    const out: string[] = [];
    for (let i = 0; i < v.length; i++) out.push(text(v.get(i)));
    return out;
  }
  const single = text(v);
  return single ? [single] : [];
}

export function describeWidget(
  pdf: mupdf.PDFDocument,
  widget: mupdf.PDFWidget,
  pageId: number,
  pageIndex: number,
): FormWidget {
  const obj = widget.getObject();
  const field = fieldOf(obj);
  const type = TYPE_MAP[safe(() => widget.getFieldType(), 'text')] ?? 'text';
  const flags = safe(() => widget.getFieldFlags(), 0);
  const annotFlags = safe(() => widget.getFlags(), 0);
  const acroForm = acroFormOf(pdf);
  const daObject = obj.getInheritable('DA');
  const da = parseDA(text(daObject.isNull() ? at(acroForm, 'DA') : daObject));
  const q = obj.getInheritable('Q');
  const acroQ = at(acroForm, 'Q');
  const align = (q.isNumber() ? q.asNumber() : acroQ.isNumber() ? acroQ.asNumber() : 0) as 0 | 1 | 2;
  const action = field.get('AA', 'C');
  const result: FormWidget = {
    id: obj.asIndirect(),
    pageId,
    pageIndex,
    tabIndex: 0,
    name: safe(() => widget.getName(), ''),
    label: safe(() => widget.getLabel(), ''),
    type,
    rect: widget.getBounds(),
    value: safe(() => widget.getValue(), ''),
    values: type === 'listbox' || type === 'combobox' ? choiceValues(field) : [],
    maxLen: type === 'text' ? Math.max(0, safe(() => widget.getMaxLen(), 0)) : 0,
    multiline: type === 'text' && (flags & TX_MULTILINE) !== 0,
    password: type === 'text' && (flags & TX_PASSWORD) !== 0,
    comb: type === 'text' && (flags & TX_COMB) !== 0,
    editable: type === 'combobox' && (flags & CH_EDIT) !== 0,
    multiSelect: type === 'listbox' && (flags & CH_MULTI_SELECT) !== 0,
    readOnly: (flags & FF_READ_ONLY) !== 0,
    required: (flags & FF_REQUIRED) !== 0,
    noToggleToOff: type === 'radio' && (flags & BTN_NO_TOGGLE_TO_OFF) !== 0,
    fontSize: da.size,
    textColor: da.color,
    align: align === 1 || align === 2 ? align : 0,
    hidden: (annotFlags & (ANNOT_HIDDEN | ANNOT_NO_VIEW)) !== 0,
    hasCalculation: !action.isNull(),
  };
  if (type === 'checkbox' || type === 'radio') {
    const onState = onStateOf(obj) ?? 'Yes';
    const as = obj.get('AS');
    result.onState = onState;
    result.exportValue = exportValueOf(field, onState);
    result.checked = as.isName() ? as.asName() === onState : result.value === onState;
    if (!result.value) result.value = 'Off';
  }
  if (type === 'combobox' || type === 'listbox') result.options = optionsOf(widget);
  if (type === 'signature') result.signed = !field.getInheritable('V').isNull();
  return result;
}

function sortByTabs(widgets: FormWidget[], tabs: string): FormWidget[] {
  if (tabs !== 'R' && tabs !== 'C') return widgets;
  const along = tabs === 'R' ? 1 : 0; // R: rows top-to-bottom; C: columns left-to-right
  const across = 1 - along;
  const center = (w: FormWidget, axis: number) => (w.rect[axis] + w.rect[axis + 2]) / 2;
  const size = (w: FormWidget, axis: number) => w.rect[axis + 2] - w.rect[axis];
  const sorted = [...widgets].sort((a, b) => center(a, along) - center(b, along));
  const groups: FormWidget[][] = [];
  for (const w of sorted) {
    const group = groups.at(-1);
    const first = group?.[0];
    if (group && first && Math.abs(center(w, along) - center(first, along)) < 0.5 * Math.min(size(w, along), size(first, along)))
      group.push(w);
    else groups.push([w]);
  }
  return groups.flatMap((group) => group.sort((a, b) => a.rect[across] - b.rect[across]));
}

/** Every widget in the document, in tab order (page order, then the page's /Tabs or annotation order). */
export function listWidgets(ctx: EngineContext, docId: string): FormWidget[] {
  const pdf = ctx.get(docId).pdf;
  const out: FormWidget[] = [];
  for (let index = 0; index < pdf.countPages(); index++) {
    const pageObject = pdf.findPage(index);
    const annots = pageObject.get('Annots');
    if (!annots.isArray() || annots.length === 0) continue;
    const pageId = ctx.pageInfo(docId, index).id;
    const page = pdf.loadPage(index);
    try {
      const widgets = page.getWidgets().map((w) => describeWidget(pdf, w, pageId, index));
      const tabs = pageObject.get('Tabs');
      out.push(...sortByTabs(widgets, tabs.isName() ? tabs.asName() : ''));
    } finally {
      page.destroy();
    }
  }
  out.forEach((w, i) => (w.tabIndex = i));
  return out;
}

/** Pages holding any widget of the given fields (object numbers of terminal field dictionaries). */
function forEachWidgetOfFields(
  ctx: EngineContext,
  docId: string,
  fieldNumbers: Set<number>,
  fn: (widget: mupdf.PDFWidget, pageId: number) => void,
): number[] {
  const pdf = ctx.get(docId).pdf;
  const touched: number[] = [];
  for (let index = 0; index < pdf.countPages(); index++) {
    const annots = pdf.findPage(index).get('Annots');
    if (!annots.isArray()) continue;
    let relevant = false;
    for (let k = 0; k < annots.length && !relevant; k++) {
      const entry = annots.get(k);
      if (entry.get('Subtype').isName() && entry.get('Subtype').asName() === 'Widget') {
        const field = fieldOf(entry);
        relevant = fieldNumbers.has(field.isIndirect() ? field.asIndirect() : 0);
      }
    }
    if (!relevant) continue;
    const pageId = ctx.pageInfo(docId, index).id;
    const page = pdf.loadPage(index);
    try {
      for (const widget of page.getWidgets()) {
        const field = fieldOf(widget.getObject());
        if (fieldNumbers.has(field.isIndirect() ? field.asIndirect() : 0)) fn(widget, pageId);
      }
    } finally {
      page.destroy();
    }
    touched.push(pageId);
  }
  return touched;
}

function fieldNumberOf(widget: mupdf.PDFWidget): number {
  const field = fieldOf(widget.getObject());
  return field.isIndirect() ? field.asIndirect() : widget.getObject().asIndirect();
}

/**
 * Letters the standard PDF fonts used for field appearances cannot draw (for example Arabic). MuPDF
 * leaves those letters out of the appearance it generates, so the document asks other PDF readers to
 * redraw field appearances with their own fonts, and the app shows such values over the field itself.
 */
export const OUTSIDE_STANDARD_FONTS = /[^\t\n\r\u0020-\u024f\u02b0-\u036f\u1e00-\u1eff\u2000-\u206f\u20a0-\u20bf\u2100-\u214f]/;

function askReadersToRedraw(pdf: mupdf.PDFDocument) {
  const form = pdf.getTrailer().get('Root', 'AcroForm');
  if (form.isDictionary()) form.put('NeedAppearances', true);
}

function codePoints(value: string, max: number): string {
  if (max <= 0) return value;
  return Array.from(value).slice(0, max).join('');
}

/** Sets one field value from one of its widgets. Returns the ids of every page whose widgets changed. */
export function setFieldValue(
  ctx: EngineContext,
  docId: string,
  pdf: mupdf.PDFDocument,
  args: SetValueArgs,
): number[] {
  const page = pdf.loadPage(ctx.pageIndex(docId, args.pageId));
  let fieldNumber = 0;
  try {
    const widget = page.getWidgets().find((w) => w.getObject().asIndirect() === args.id);
    if (!widget) throw new Error('This form field is no longer on the page.');
    const info = describeWidget(pdf, widget, args.pageId, 0);
    if (info.readOnly) throw new Error('This field is read-only.');
    fieldNumber = fieldNumberOf(widget);
    const field = fieldOf(widget.getObject());
    switch (info.type) {
      case 'text':
        widget.setTextValue(codePoints(String(args.value ?? ''), info.maxLen));
        break;
      case 'checkbox':
      case 'radio': {
        const want = Boolean(args.checked);
        if (want !== Boolean(info.checked) && (want || !info.noToggleToOff)) widget.toggle();
        break;
      }
      case 'combobox': {
        const value = String(args.value ?? '');
        const options = info.options ?? [];
        if (!info.editable && value && !options.some((o) => o.value === value))
          throw new Error('Choose one of the listed options.');
        widget.setChoiceValue(value);
        break;
      }
      case 'listbox': {
        const options = info.options ?? [];
        const wanted = (args.values ?? (args.value !== undefined ? [args.value] : [])).filter((v) =>
          options.some((o) => o.value === v),
        );
        const chosen = info.multiSelect ? wanted : wanted.slice(0, 1);
        // The setter marks the widget for appearance regeneration; V and I are then completed.
        widget.setChoiceValue(chosen[0] ?? '');
        const indices = chosen
          .map((v) => options.findIndex((o) => o.value === v))
          .filter((i) => i >= 0)
          .sort((a, b) => a - b);
        if (chosen.length > 1) {
          const array = pdf.newArray();
          for (const i of indices) array.push(pdf.newString(options[i].value));
          field.put('V', array);
        } else if (!chosen.length) field.delete('V');
        if (indices.length) {
          const array = pdf.newArray();
          for (const i of indices) array.push(i);
          field.put('I', array);
        } else field.delete('I');
        break;
      }
      default:
        throw new Error('This field cannot be filled here.');
    }
    if (OUTSIDE_STANDARD_FONTS.test(String(args.value ?? '')) || (args.values ?? []).some((v) => OUTSIDE_STANDARD_FONTS.test(v)))
      askReadersToRedraw(pdf);
  } finally {
    page.destroy();
  }
  const pages = forEachWidgetOfFields(ctx, docId, new Set([fieldNumber]), (w) => w.update());
  if (args.calculate) pages.push(...runCalculations(ctx, docId, pdf).pages);
  return [...new Set(pages)];
}

/** Reset like the PDF ResetForm action: V = DV where DV exists, otherwise V is removed. */
export function resetFields(ctx: EngineContext, docId: string, pdf: mupdf.PDFDocument): number[] {
  const resettable = new Set<number>();
  const fieldNumbers = new Set<number>();
  for (const w of listWidgets(ctx, docId))
    if (w.type !== 'signature' && w.type !== 'button') resettable.add(w.id);
  const pages = new Set<number>();
  for (let index = 0; index < pdf.countPages(); index++) {
    const annots = pdf.findPage(index).get('Annots');
    if (!annots.isArray() || !annots.length) continue;
    const page = pdf.loadPage(index);
    try {
      for (const widget of page.getWidgets()) {
        if (!resettable.has(widget.getObject().asIndirect())) continue;
        const obj = widget.getObject();
        const field = fieldOf(obj);
        const number = fieldNumberOf(widget);
        const type = TYPE_MAP[widget.getFieldType()] ?? 'text';
        const dv = field.getInheritable('DV');
        if (!fieldNumbers.has(number)) {
          fieldNumbers.add(number);
          if (type === 'text') widget.setTextValue(dv.isNull() ? '' : text(dv));
          else if (type === 'combobox' || type === 'listbox') {
            widget.setChoiceValue(dv.isArray() ? text(dv.get(0)) : text(dv));
            field.delete('I');
          }
          if (dv.isNull()) field.delete('V');
          else field.put('V', dv);
        }
        if (type === 'checkbox' || type === 'radio') {
          const v = field.getInheritable('V');
          const normal = obj.get('AP', 'N');
          const state = v.isName() && (!normal.isDictionary() || !normal.get(v.asName()).isNull()) ? v.asName() : 'Off';
          obj.put('AS', pdf.newName(state));
        }
        widget.update();
        pages.add(ctx.pageInfo(docId, index).id);
      }
    } finally {
      page.destroy();
    }
  }
  return [...pages];
}

// ---------------------------------------------------------------------------------------------
// Declarative calculation support (no script engine; only Acrobat's AFSimple_Calculate).

type CalcOp = 'SUM' | 'PRD' | 'AVG' | 'MIN' | 'MAX';
export interface ParsedCalculation {
  op: CalcOp;
  fields: string[];
}

function scriptOf(action: mupdf.PDFObject): string {
  if (!action.isDictionary()) return '';
  const js = action.get('JS');
  return text(js);
}

export function parseCalculation(script: string): ParsedCalculation | null {
  const match = /^\s*AFSimple_Calculate\s*\(\s*["'](SUM|PRD|AVG|MIN|MAX)["']\s*,\s*([\s\S]*)\)\s*;?\s*$/.exec(script);
  if (!match) return null;
  const list = match[2].trim();
  let names: string[] = [];
  const arrayMatch = /^new\s+Array\s*\(([\s\S]*)\)$/.exec(list) || /^\[([\s\S]*)\]$/.exec(list);
  if (arrayMatch) {
    const literal = /"((?:[^"\\]|\\.)*)"|'((?:[^'\\]|\\.)*)'/g;
    let m: RegExpExecArray | null;
    while ((m = literal.exec(arrayMatch[1]))) names.push((m[1] ?? m[2]).replace(/\\(.)/g, '$1'));
  } else {
    const single = /^"((?:[^"\\]|\\.)*)"$|^'((?:[^'\\]|\\.)*)'$/.exec(list);
    if (!single) return null;
    names = (single[1] ?? single[2]).split(',');
  }
  names = names.map((n) => n.trim()).filter(Boolean);
  if (!names.length) return null;
  return { op: match[1] as CalcOp, fields: names };
}

function toNumber(value: string): number {
  const cleaned = value.replace(/[\s\u00a0]/g, '');
  if (!cleaned) return 0;
  const european = /^[+-]?\d{1,3}(\.\d{3})*(,\d+)?$/.test(cleaned) || /^[+-]?\d+,\d+$/.test(cleaned);
  const normal = european ? cleaned.replace(/\./g, '').replace(',', '.') : cleaned.replace(/,/g, '');
  const number = Number(normal.replace(/[^\d.+-eE]/g, ''));
  return Number.isFinite(number) ? number : 0;
}

export function formatNumber(value: number, formatScript: string): string {
  const match = /AFNumber_Format\s*\(\s*(\d+)\s*,\s*(\d+)/.exec(formatScript);
  if (!match) return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(15)));
  const decimals = Math.min(10, Number(match[1]));
  const style = Number(match[2]);
  const fixed = Math.abs(value).toFixed(decimals);
  const [whole, fraction] = fixed.split('.');
  const group = style === 0 || style === 2 ? (style === 0 ? ',' : '.') : '';
  const point = style === 2 || style === 3 ? ',' : '.';
  const grouped = group ? whole.replace(/\B(?=(\d{3})+(?!\d))/g, group) : whole;
  return `${value < 0 ? '-' : ''}${grouped}${fraction !== undefined ? point + fraction : ''}`;
}

export function countCalculations(pdf: mupdf.PDFDocument): { supported: number; unsupported: number } {
  let supported = 0;
  let unsupported = 0;
  const fields = at(acroFormOf(pdf), 'Fields');
  const visit = (field: mupdf.PDFObject, depth: number) => {
    if (depth > 32 || !field.isDictionary()) return;
    const action = field.get('AA', 'C');
    if (!action.isNull()) {
      if (parseCalculation(scriptOf(action))) supported++;
      else unsupported++;
    }
    const kids = field.get('Kids');
    if (kids.isArray()) for (let i = 0; i < kids.length; i++) visit(kids.get(i), depth + 1);
  };
  if (fields.isArray()) for (let i = 0; i < fields.length; i++) visit(fields.get(i), 0);
  return { supported, unsupported };
}

export function documentHasScripts(pdf: mupdf.PDFDocument): boolean {
  const root = pdf.getTrailer().get('Root');
  const open = root.get('OpenAction');
  if (open.isDictionary() && open.get('S').isName() && open.get('S').asName() === 'JavaScript') return true;
  if (!root.get('Names', 'JavaScript').isNull()) return true;
  if (!root.get('AA').isNull()) return true;
  let found = false;
  const fields = root.get('AcroForm', 'Fields');
  const visit = (field: mupdf.PDFObject, depth: number) => {
    if (found || depth > 32 || !field.isDictionary()) return;
    if (!field.get('AA').isNull()) found = true;
    const action = field.get('A');
    if (action.isDictionary() && action.get('S').isName() && action.get('S').asName() === 'JavaScript') found = true;
    const kids = field.get('Kids');
    if (kids.isArray()) for (let i = 0; i < kids.length; i++) visit(kids.get(i), depth + 1);
  };
  if (fields.isArray()) for (let i = 0; i < fields.length; i++) visit(fields.get(i), 0);
  return found;
}

/** Evaluates supported calculations in /CO order (then document order) and writes results. */
export function runCalculations(
  ctx: EngineContext,
  docId: string,
  pdf: mupdf.PDFDocument,
): { pages: number[]; updated: number } {
  const widgets = listWidgets(ctx, docId);
  const byName = new Map<string, FormWidget>();
  for (const w of widgets) if (!byName.has(w.name)) byName.set(w.name, w);
  const acroForm = acroFormOf(pdf);
  const order: mupdf.PDFObject[] = [];
  const seen = new Set<number>();
  const co = at(acroForm, 'CO');
  if (co.isArray())
    for (let i = 0; i < co.length; i++) {
      const ref = co.get(i);
      if (ref.isIndirect() && !seen.has(ref.asIndirect())) {
        seen.add(ref.asIndirect());
        order.push(ref);
      }
    }
  for (const w of widgets) {
    if (!w.hasCalculation) continue;
    const page = pdf.loadPage(w.pageIndex);
    try {
      const widget = page.getWidgets().find((x) => x.getObject().asIndirect() === w.id);
      const field = widget && fieldOf(widget.getObject());
      if (field && field.isIndirect() && !seen.has(field.asIndirect())) {
        seen.add(field.asIndirect());
        order.push(field);
      }
    } finally {
      page.destroy();
    }
  }
  const values = new Map<string, string>();
  for (const w of widgets) if (!values.has(w.name)) values.set(w.name, w.type === 'checkbox' || w.type === 'radio' ? (w.value === 'Off' ? '' : (w.exportValue ?? w.value)) : w.value);
  const pages = new Set<number>();
  let updated = 0;
  for (const field of order) {
    const parsed = parseCalculation(scriptOf(field.get('AA', 'C')));
    if (!parsed) continue;
    const name = fullName(field);
    const target = byName.get(name);
    // Calculated fields are usually read-only for the user; the form's own calculation still writes them.
    if (!target || target.type !== 'text') continue;
    const numbers = parsed.fields.map((f) => toNumber(values.get(f) ?? ''));
    let result = 0;
    if (numbers.length) {
      if (parsed.op === 'SUM') result = numbers.reduce((a, b) => a + b, 0);
      else if (parsed.op === 'PRD') result = numbers.reduce((a, b) => a * b, 1);
      else if (parsed.op === 'AVG') result = numbers.reduce((a, b) => a + b, 0) / numbers.length;
      else if (parsed.op === 'MIN') result = Math.min(...numbers);
      else result = Math.max(...numbers);
    }
    const formatted = formatNumber(result, scriptOf(field.get('AA', 'F')));
    values.set(name, formatted);
    if (target.value === formatted) continue;
    const number = field.asIndirect();
    let wrote = false;
    pages.add(target.pageId);
    for (const pageId of forEachWidgetOfFields(ctx, docId, new Set([number]), (w) => {
      if (!wrote) {
        w.setTextValue(formatted);
        wrote = true;
      }
      w.update();
    }))
      pages.add(pageId);
    updated++;
  }
  return { pages: [...pages], updated };
}

function fullName(field: mupdf.PDFObject): string {
  const parts: string[] = [];
  let node: mupdf.PDFObject = field;
  for (let depth = 0; depth < 32 && node.isDictionary(); depth++) {
    const t = node.get('T');
    if (t.isString()) parts.unshift(t.asString());
    node = node.get('Parent');
  }
  return parts.join('.');
}
